<!-- The three look buttons, shared by the floating switch (wide screens) and the menu drawer
     (narrow screens). enhance.js wires every .look-btn on the page and keeps aria-pressed in sync. -->
<button type="button" class="look-btn look-btn-morning" data-look="morning" aria-pressed="false" aria-label="Morning" title="Morning"><svg class="ico" aria-hidden="true"><use href="#i-sun"/></svg></button>
<button type="button" class="look-btn look-btn-dusk" data-look="dusk" aria-pressed="false" aria-label="Dusk" title="Dusk"><svg class="ico" aria-hidden="true"><use href="#i-dusk"/></svg></button>
<button type="button" class="look-btn look-btn-night" data-look="night" aria-pressed="false" aria-label="Night" title="Night"><svg class="ico" aria-hidden="true"><use href="#i-moon"/></svg></button>
